SELECT d.id, d.create_user_id, d.create_user_name, d.create_time, d.update_user_id, d.update_user_name, d.update_time, d.version, d.is_deleted, d.source_detail_id, d.main_id, d.asset_code, d.asset_location_id, d.qty, d.supplier_id, d.supplier_name, d.use_dept_name, d.use_dept_id, d.cost_type, d.remark FROM asset_card_detail d INNER JOIN asset_card c ON d.main_id = c.id WHERE d.is_deleted = false AND c.is_deleted = false AND c.approve_status = 'approve'
AND c.code >= #{cardCodeStart}
AND c.code <= #{cardCodeEnd}
